import{_ as e,C as i,c as n,o as t,j as l,b as o,a0 as a,a as r,w as s,G as d,a1 as u}from"./chunks/framework.DKRgXLPU.js";const g=JSON.parse('{"title":"Trainingsoefeningen","description":"","frontmatter":{},"headers":[],"relativePath":"nl/education/training/drills.md","filePath":"nl/education/training/drills.md"}');const h=e({name:"nl/education/training/drills.md"},[["render",function(e,g,h,p,k,c){const m=i("Mermaid");return t(),n("div",null,[g[1]||(g[1]=l("h1",{id:"trainingsoefeningen",tabindex:"-1"},[r("Trainingsoefeningen "),l("a",{class:"header-anchor",href:"#trainingsoefeningen","aria-label":'Permalink to "Trainingsoefeningen"'},"​")],-1)),g[2]||(g[2]=l("p",null,"Hieronder vind je beproefde oefeningen die door topspelers worden gebruikt. Elke oefening heeft een specifiek doel - kies de oefening die het beste aansluit bij jouw ontwikkelingsbehoeften.",-1)),g[3]||(g[3]=l("div",{class:"tip custom-block"},[l("p",{class:"custom-block-title"},"Het Grote Idee"),l("p",null,[l("strong",null,"Elke oefening heeft een specifiek doel."),r(" Gooi niet zomaar willekeurig met de boules, maar kies oefeningen die je zwakke punten aanpakken en je doelen ondersteunen. Houd je voortgang bij om je verbetering te zien.")])],-1)),(t(),o(u,null,{default:s(()=>[d(m,{id:"mermaid-11",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BTrainingsoefeningen%5D%20--%3E%20B%5BAanwijsoefeningen%5D%0A%20%20%20%20A%20--%3E%20C%5BSchietoefeningen%5D%0A%20%20%20%20A%20--%3E%20D%5BMentale%20oefeningen%5D%0A%20%20%20%20A%20--%3E%20E%5BSpelsimulatie%5D%0A%0A%20%20%20%20B%20--%3E%20F%5BNauwkeurigheid%5D%0A%20%20%20%20B%20--%3E%20G%5BAfstandsregeling%5D%0A%0A%20%20%20%20C%20--%3E%20H%5BTrefpercentage%5D%0A%20%20%20%20C%20--%3E%20I%5BDrukschieten%5D%0A%0A%20%20%20%20D%20--%3E%20J%5BRoutinepraktijk%5D%0A%20%20%20%20D%20--%3E%20K%5BVisualisatie%5D%0A%0A%20%20%20%20E%20--%3E%20L%5BCompetitiebereidheid%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23e8f5e9%0A%20%20%20%20style%20B%20fill%3A%23e3f2fd%0A%20%20%20%20style%20C%20fill%3A%23fff4e1%0A%20%20%20%20style%20D%20fill%3A%23f3e5f5%0A%20%20%20%20style%20E%20fill%3A%23fff4e1%0A"})]),fallback:s(()=>[...g[0]||(g[0]=[r(" Loading... ",-1)])]),_:1})),g[4]||(g[4]=a('<h2 id="aanwijsoefeningen" tabindex="-1">Aanwijsoefeningen <a class="header-anchor" href="#aanwijsoefeningen" aria-label="Permalink to &quot;Aanwijsoefeningen&quot;">​</a></h2><h3 id="de-steeg" tabindex="-1">De steeg <a class="header-anchor" href="#de-steeg" aria-label="Permalink to &quot;De steeg&quot;">​</a></h3><p><strong>Doel:</strong> Het isoleren van de afwerphoek en de lijnconsistentie.</p><p><strong>Installatie:</strong></p><ul><li>Plaats twee markeringen op 30-40 cm afstand van elkaar, op ongeveer 1 meter van de cirkel.</li><li>Het doel bevindt zich op 7-9 meter afstand.</li></ul><p><strong>Oefening:</strong></p><ul><li>Gooi door het &quot;steegje&quot; (tussen de markeringen)</li><li>Elke worp die een marker raakt, is &quot;dood&quot;.</li><li>Focus op een consistent afgiftepunt.</li></ul><p><strong>Progressie:</strong></p><ul><li>Versmaller het steegje naarmate je beter wordt.</li><li>Varieer de afstand tot het doel.</li><li>Voeg een specifieke landingszone toe</li></ul><h3 id="precisiezones" tabindex="-1">Precisiezones <a class="header-anchor" href="#precisiezones" aria-label="Permalink to &quot;Precisiezones&quot;">​</a></h3><p><strong>Doel:</strong> Nauwkeurigheid ontwikkelen op specifieke gebieden</p><p><strong>Installatie:</strong></p><ul><li>Markeer zones rond een doelwit (bijvoorbeeld cirkels op 20 cm, 40 cm, 60 cm).</li><li>Of gebruik natuurlijke markeringen in het terrein.</li></ul><p><strong>Score:</strong></p><ul><li>Binnen 20 cm: 3 punten</li><li>Binnen 40 cm: 2 punten</li><li>Binnen 60 cm: 1 punt</li><li>Buiten: 0 punten</li></ul><p><strong>Oefening:</strong></p><ul><li>Gooi 10 boules en houd je score bij.</li><li>Doel: Voortdurende verbetering gedurende de sessies</li></ul><h3 id="afstandsvariatie" tabindex="-1">Afstandsvariatie <a class="header-anchor" href="#afstandsvariatie" aria-label="Permalink to &quot;Afstandsvariatie&quot;">​</a></h3><p><strong>Doel:</strong> Dieptecontrole ontwikkelen</p><p><strong>Installatie:</strong></p><ul><li>Plaats doelen op 6m, 7m, 8m, 9m en 10m afstand.</li></ul><p><strong>Oefening:</strong></p><ul><li>Gooi naar elke afstand in willekeurige volgorde.</li><li>Partner roept in de verte</li><li>Focus op het aanpassen van het gewicht, niet op de techniek.</li></ul><p><strong>Variatie:</strong></p><ul><li>Voeg &quot;korte&quot; en &quot;lange&quot; aanroepen toe nadat je ze hebt vrijgegeven.</li><li>Aanpassing tijdens de vlucht is noodzakelijk (ontwikkelt gevoel).</li></ul><h2 id="schietoefeningen" tabindex="-1">Schietoefeningen <a class="header-anchor" href="#schietoefeningen" aria-label="Permalink to &quot;Schietoefeningen&quot;">​</a></h2><h3 id="de-schietladder" tabindex="-1">De schietladder <a class="header-anchor" href="#de-schietladder" aria-label="Permalink to &quot;De schietladder&quot;">​</a></h3><p><strong>Doel:</strong> Nauwkeurigheid opbouwen onder steeds hogere druk</p><p><strong>Installatie:</strong></p><ul><li>Plaats een doelboule op 6 meter afstand.</li><li>Markeer afstanden op 7m, 8m, 9m, 10m</li></ul><p><strong>Oefening:</strong></p><ul><li>Begin op 6 meter afstand.</li><li>Geraakt = één meter achteruitgaan</li><li>Miss = één meter vooruitgaan (of opnieuw beginnen)</li><li>Doel: 10 meter bereiken</li></ul><p><strong>Variaties:</strong></p><ul><li>Strikte versie: Bij elke misser moet je terug naar 6 meter.</li><li>Tijdsgebonden versie: Hoe ver kom je in 10 minuten?</li><li>Teamversie: Wissel af met je partner</li></ul><h3 id="de-barriere-blox" tabindex="-1">De Barrière (Blox) <a class="header-anchor" href="#de-barriere-blox" aria-label="Permalink to &quot;De Barrière (Blox)&quot;">​</a></h3><p><strong>Doel:</strong> Hoge boogschieten afdwingen</p><p><strong>Installatie:</strong></p><ul><li>Plaats een barrière (stok, touw of obstakel) tussen jou en het doelwit.</li><li>De barrière moet hoog genoeg zijn om een lob te vereisen.</li></ul><p><strong>Oefening:</strong></p><ul><li>Je moet de hindernis passeren om het doel te raken.</li><li>Elke worp die de barrière raakt, is &quot;dood&quot;.</li><li>Ontwikkelt een hoog afgiftepunt</li></ul><p><strong>Waarom dit belangrijk is:</strong></p><ul><li>Bij wedstrijden is het vaak nodig om over obstakels heen te schieten.</li><li>Vergroot de veelzijdigheid van je schietvaardigheid.</li></ul><h3 id="hindernisbaan" tabindex="-1">Hindernisbaan <a class="header-anchor" href="#hindernisbaan" aria-label="Permalink to &quot;Hindernisbaan&quot;">​</a></h3><p><strong>Doel:</strong> Het ontwikkelen van fotografie vanuit verschillende hoeken</p><p><strong>Installatie:</strong></p><ul><li>Plaats de doelboule in het midden.</li><li>Voeg obstakels (andere boules, markeringen) eromheen toe.</li></ul><p><strong>Oefening:</strong></p><ul><li>Fotografeer vanuit verschillende posities rondom de cirkel.</li><li>Je moet de invalshoek vinden die werkt.</li><li>Ontwikkelt het lezen van schietlijnen.</li></ul><h2 id="mentale-trainingsoefeningen" tabindex="-1">Mentale trainingsoefeningen <a class="header-anchor" href="#mentale-trainingsoefeningen" aria-label="Permalink to &quot;Mentale trainingsoefeningen&quot;">​</a></h2><h3 id="routinematige-herhaling" tabindex="-1">Routinematige herhaling <a class="header-anchor" href="#routinematige-herhaling" aria-label="Permalink to &quot;Routinematige herhaling&quot;">​</a></h3><p><strong>Doel:</strong> Uw voorbereiding op de foto automatiseren</p><p><strong>Oefening:</strong></p><ul><li>Oefen je volledige routine zonder te gooien.</li><li>Doorloop elke stap zorgvuldig.</li><li>Doe 10-20 herhalingen.</li><li>Voeg vervolgens de worp toe.</li></ul><p><strong>Focus:</strong></p><ul><li>Consistente timing</li><li>Duidelijke overgang van denken naar uitvoeren</li><li>Steeds dezelfde routine.</li></ul><h3 id="drukpunten" tabindex="-1">Drukpunten <a class="header-anchor" href="#drukpunten" aria-label="Permalink to &quot;Drukpunten&quot;">​</a></h3><p><strong>Doel:</strong> Oefenen met presteren onder druk</p><p><strong>Installatie:</strong></p><ul><li>Creëer een scenario dat absoluut noodzakelijk is.</li><li>Stel consequenties vast voor het niet nakomen van een afspraak.</li></ul><p><strong>Voorbeelden:</strong></p><ul><li>&quot;Maak er 3 op een rij of begin opnieuw&quot;</li><li>&quot;Mis en doe 10 push-ups&quot;</li><li>&quot;Maak je doelwit bekend voordat je gooit.&quot;</li></ul><p><strong>Sleutel:</strong></p><ul><li>De druk moet echt aanvoelen.</li><li>Oefen je mentale reactie op druk.</li><li>Volg je routine precies zoals tijdens de wedstrijd.</li></ul><h3 id="herstelpraktijk" tabindex="-1">Herstelpraktijk <a class="header-anchor" href="#herstelpraktijk" aria-label="Permalink to &quot;Herstelpraktijk&quot;">​</a></h3><p><strong>Doel:</strong> De gewoonte ontwikkelen om snel mentaal te resetten.</p><p><strong>Oefening:</strong></p><ul><li>Opzettelijk een slechte boule gooien</li><li>Pas direct de SOAS-methode toe (Stop, Observeer, Accepteer, Glijd door).</li><li>Gooi de volgende boule met volle overgave.</li></ul><p><strong>Focus:</strong></p><ul><li>Sta niet te lang stil bij de gemiste kans.</li><li>Reset volledig voor de volgende worp.</li><li>Houd een positieve lichaamstaal aan.</li></ul><h2 id="spelsimulatieoefeningen" tabindex="-1">Spelsimulatieoefeningen <a class="header-anchor" href="#spelsimulatieoefeningen" aria-label="Permalink to &quot;Spelsimulatieoefeningen&quot;">​</a></h2><h3 id="het-genot-van-het-milieu" tabindex="-1">Het genot van het milieu <a class="header-anchor" href="#het-genot-van-het-milieu" aria-label="Permalink to &quot;Het genot van het milieu&quot;">​</a></h3><p><strong>Doel:</strong> Ritmeblokkades doorbreken, veelzijdigheid vergroten</p><p><strong>Oefening:</strong></p><ul><li>Wissel bij elke worp af tussen wijzen en schieten.</li><li>Geen twee opeenvolgende worpen van hetzelfde type.</li><li>Ontwikkelt het vermogen om van modus te wisselen.</li></ul><h3 id="scenario-spelen" tabindex="-1">Scenario spelen <a class="header-anchor" href="#scenario-spelen" aria-label="Permalink to &quot;Scenario spelen&quot;">​</a></h3><p><strong>Doel:</strong> Het oefenen van tactische besluitvorming.</p><p><strong>Installatie:</strong></p><ul><li>Creëer realistische spelsituaties.</li><li>Ken scores en boule-tellingen toe.</li></ul><p><strong>Voorbeelden:</strong></p><ul><li>&quot;Je staat met 10-8 achter, de tegenstander heeft 2 punten, jij hebt nog 2 boules over.&quot;</li><li>&quot;Gelijkspel 6-6, jij hebt de laatste boule, zij hebben 1 punt&quot;</li></ul><p><strong>Oefening:</strong></p><ul><li>Beslis wat je gaat doen</li><li>Voer het met volledige toewijding uit.</li><li>Evalueer de beslissing achteraf.</li></ul><h3 id="wedstrijd-spelen-met-regels" tabindex="-1">Wedstrijd spelen met regels <a class="header-anchor" href="#wedstrijd-spelen-met-regels" aria-label="Permalink to &quot;Wedstrijd spelen met regels&quot;">​</a></h3><p><strong>Doel:</strong> Competitiesimulatie</p><p><strong>Variaties:</strong></p><ul><li>Speel tot 13 (hele wedstrijd)</li><li>Speel tot 7 (korter, meer spellen)</li><li>&quot;Drukpunten&quot; - bepaalde doelen die dubbel zoveel waard zijn.</li><li>&quot;Sudden death&quot; - de eerste die een end verliest, verliest het spel.</li></ul><h2 id="het-bijhouden-van-je-oefeningen" tabindex="-1">Het bijhouden van je oefeningen <a class="header-anchor" href="#het-bijhouden-van-je-oefeningen" aria-label="Permalink to &quot;Het bijhouden van je oefeningen&quot;">​</a></h2><p>Houd voor elke oefening een logboek bij:</p><table tabindex="0"><thead><tr><th>Datum</th><th>Oefening</th><th>Score/Result</th><th>Notities</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td></tr></tbody></table><p><strong>Volg de ontwikkeling over tijd:</strong></p><ul><li>Gaat het beter met je?</li><li>Welke oefeningen helpen het meest?</li><li>Waar loop je tegenaan?</li></ul><h2 id="een-oefensessie-opbouwen" tabindex="-1">Een oefensessie opbouwen <a class="header-anchor" href="#een-oefensessie-opbouwen" aria-label="Permalink to &quot;Een oefensessie opbouwen&quot;">​</a></h2><h3 id="opwarming-10-min" tabindex="-1">Opwarming (10 min) <a class="header-anchor" href="#opwarming-10-min" aria-label="Permalink to &quot;Opwarming (10 min)&quot;">​</a></h3><ul><li>Eenvoudige worpen om los te komen</li><li>Geen druk, voel het gewoon</li></ul><h3 id="technische-focus-20-30-min" tabindex="-1">Technische focus (20-30 min) <a class="header-anchor" href="#technische-focus-20-30-min" aria-label="Permalink to &quot;Technische focus (20-30 min)&quot;">​</a></h3><ul><li>Een of twee oefeningen gericht op specifieke vaardigheden.</li><li>Geblokkeerde oefening voor nieuwe vaardigheden</li><li>Willekeurige oefening voor reeds verworven vaardigheden</li></ul><h3 id="druk-spelsimulatie-20-30-min" tabindex="-1">Druk-/spelsimulatie (20-30 min) <a class="header-anchor" href="#druk-spelsimulatie-20-30-min" aria-label="Permalink to &quot;Druk-/spelsimulatie (20-30 min)&quot;">​</a></h3><ul><li>Voeg consequenties toe</li><li>Creëer realistische scenario&#39;s</li><li>Oefen mentale vaardigheden</li></ul><h3 id="afkoelen-10-min" tabindex="-1">Afkoelen (10 min) <a class="header-anchor" href="#afkoelen-10-min" aria-label="Permalink to &quot;Afkoelen (10 min)&quot;">​</a></h3><ul><li>Gemakkelijke worpen</li><li>Reflecteer op de sessie.</li><li>Noteer waaraan je vervolgens moet werken.</li></ul><h2 id="belangrijkste-conclusie" tabindex="-1">Belangrijkste conclusie <a class="header-anchor" href="#belangrijkste-conclusie" aria-label="Permalink to &quot;Belangrijkste conclusie&quot;">​</a></h2><blockquote><p>Boormachines zijn gereedschappen. Kies het juiste gereedschap voor wat je wilt bouwen.</p></blockquote><p>Gooi niet zomaar met de boules. Train met een doel.</p>',103))])}]]);export{g as __pageData,h as default};
